def solve(grid, start, goal):
    def is_valid(row, col):
        return 0 <= row < len(grid) and 0 <= col < len(grid[0]) and grid[row][col] == '.'

    def backtrack(current_path, visited):
        row, col = current_path[-1]
        if (row, col) == goal:
            return current_path.copy()

        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        for dr, dc in directions:
            next_row, next_col = row + dr, col + dc
            if is_valid(next_row, next_col) and (next_row, next_col) not in visited:
                visited.add((next_row, next_col))
                current_path.append((next_row, next_col))
                result = backtrack(current_path, visited)
                if result:
                    return result
                current_path.pop()
                visited.remove((next_row, next_col))
        return []

    if not is_valid(*start) or not is_valid(*goal):
        return []

    visited = set()
    visited.add(start)
    path = [start]
    return backtrack(path, visited)
