            return None

        visited.add((r, c))
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc) and (nr, nc) not in visited:
                result = dfs(nr, nc, depth - 1, path + [(r, c)], visited)
                if result:
                    return result
        visited.remove((r, c))
        return None

    max_depth = 2 * max(len(grid), len(grid[0]))  # Upper bound for depth
    for depth in range(1, max_depth + 1):
        visited = set()
        result = dfs(start[0], start[1], depth, [], visited)
        if result:
            return result
    return []
