def solve(grid, start, goal):
    def is_valid(pos):
        row, col = pos
        return 0 <= row < len(grid) and 0 <= col < len(grid[0]) and grid[row][col] == '.'

    def get_neighbors(pos):
        row, col = pos
        neighbors = []
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            new_row, new_col = row + dr, col + dc
            if is_valid((new_row, new_col)):
                neighbors.append((new_row, new_col))
        return neighbors

    def heuristic(pos, goal):
        return abs(pos[0] - goal[0]) + abs(pos[1] - goal[1])

    # Hill Climbing with heuristic
    current = start
    path = [current]
    visited = set()
    visited.add(current)

    while True:
        neighbors = get_neighbors(current)
        if not neighbors:
            break  # No more moves, stuck

        # Find the neighbor with the best heuristic value
        best_neighbor = None
        best_heuristic = float('inf')
        for neighbor in neighbors:
            h = heuristic(neighbor, goal)
            if h < best_heuristic:
                best_heuristic = h
                best_neighbor = neighbor

        # If the best neighbor is not better than current, we're stuck
        if best_heuristic >= heuristic(current, goal):
            break

        # Move to the best neighbor
        current = best_neighbor
        if current == goal:
            path.append(current)
            break
        if current in visited:
            break  # Prevent cycles
        visited.add(current)
        path.append(current)

    # Check if goal is reached
    if path[-1] == goal:
        return path
    else:
        return []
